parameters.jsCode:
const outputItems = [];
for (const item of $input.all()) {
  try {
    // Extract the JSON string from the AI response
    let jsonString = item.json.content[0].text;

    // Remove markdown code block markers if present
    jsonString = jsonString.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

    // Parse the JSON string
    const parsedData = JSON.parse(jsonString);

    // Organize the data with Spanish field names
    const organizedData = {
      "Período": parsedData.periodo,
      "Total del débito Fiscal del Período": parsedData.totalDebitoFiscal,
      "Total del Crédito Fiscal de Período": parsedData.totalCreditoFiscal,
      "Saldo Técnico a Favor del Contribuyente del período anterior": parsedData.saldoTecnicoContribuyentePeriodoAnterior,
      "Saldo Técnico a favor de ARCA (Determinación)": parsedData.saldoTecnicoARCA_Determinacion,
      "Saldo Técnico a favor de ARCA (Posición Mensual)": parsedData.saldoTecnicoARCA_Posicion,
      "Saldo a favor del libre disponibilidad del período anterior neto de usos": parsedData.saldoLibreDisponibilidad,
      "Total de retenciones, percepciones y pagos a cuenta neto de restituciones": parsedData.totalRetencionesPercepcionesPagos,
      "Saldo de impuesto a favor de ARCA": parsedData.saldoImpuestoARCA
    };

    outputItems.push({ json: organizedData });

  } catch (error) {
    // Handle errors
    outputItems.push({
      json: {
        error: "Failed to parse data",
        errorMessage: error.message,
        rawData: JSON.stringify(item.json)
      }
    });
  }
}
return outputItems;
